    let mut g: u32 = 0;
    let mut b: u32 = 0;

    let mode_in_ref = &*mode_in;
    let mode_out_ref = &*mode_out;

    let mul: u32 = 65535 / ((1u32 << mode_in_ref.bitdepth) - 1u32);
    let shift: u32 = 16 - mode_out_ref.bitdepth;

    // input conversion to 16-bit RGB
