pub unsafe fn readChunk_gAMA(
    info: *mut LodePNGInfo,
    data: *const ::core::ffi::c_uchar,
    chunkLength: usize,
) -> u32 {
    // keep exact behavior: check length first
    if chunkLength != 4 {
        return 96; // invalid gAMA chunk size
    }

    // local helper to index into the data pointer like C's data[i]
    unsafe fn at(ptr: *const ::core::ffi::c_uchar, idx: usize) -> u32 {
        *ptr.add(idx) as u32
    }

    // info->gama_defined = 1;
    (*info).gama_defined = 1;

    // info->gama_gamma = 16777216u * data[0] + 65536u * data[1] + 256u * data[2] + data[3];
    (*info).gama_gamma =
        16777216u32 * at(data, 0) +
        65536u32   * at(data, 1) +
        256u32     * at(data, 2) +
        at(data, 3);

    0 // OK
}
