    let mut d: libc::size_t = 0;
    // lodepng_addofl returns nonzero on overflow (equivalent to 'if(lodepng_addofl(a, b, &d)) return 1;')
    if unsafe { lodepng_addofl(a, b, &mut d as *mut libc::size_t) } != 0 {
